import { readFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const catalogData = JSON.parse(readFileSync(join(__dirname, "catalog", "menu.json"), "utf8"));
const categoriesData = JSON.parse(readFileSync(join(__dirname, "catalog", "categories.json"), "utf8"));
const searchIndexData = JSON.parse(readFileSync(join(__dirname, "catalog", "search-index.json"), "utf8"));

export const catalog = [...catalogData];

export function listCatalog({ query, price_min, price_max, category, limit = 50, offset = 0 } = {}) {
  let r = [...catalog];
  if (query) {
    const q = query.toLowerCase();
    r = r.filter(p => (searchIndexData[p.id] || "").includes(q));
  }
  if (category) r = r.filter(p => p.category === category);
  if (price_min != null) r = r.filter(p => p.price >= price_min * 100);
  if (price_max != null) r = r.filter(p => p.price <= price_max * 100);
  const total = r.length;
  const safeLimit = Math.min(Math.max(1, limit), 200);
  const safeOffset = Math.max(0, offset);
  const products = r.slice(safeOffset, safeOffset + safeLimit);
  return { count: products.length, total, offset: safeOffset, limit: safeLimit, products };
}
export function getProduct(id) { return catalog.find(p => p.id === id) || null; }
export function calcTotal(items) {
  let total = 0; const details = [];
  for (const { id, qty } of items) {
    const p = getProduct(id); if (!p) throw new Error(`unknown product ${id}`);
    if (qty > p.stock) throw new Error(`out of stock ${id}`);
    const line = p.price * qty;
    total += line;
    details.push({ ...p, qty, line });
  }
  return { total, details };
}
export { categoriesData, searchIndexData };
